import React, { useState, useEffect } from "react";
import api from "../api/api";
import { useNavigate } from "react-router-dom";
import SEO from "./SEO";

export default function ProductList() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    api
      .get("/products")
      .then((res) => setProducts(res.data))
      .finally(() => setLoading(false));
  }, []);

  const handleAffiliateClick = async (product) => {
    api.post(`/products/${product._id}/click`).catch(() => {});
    window.open(product.affiliateLink, "_blank", "noopener,noreferrer");
  };

  return (
    <div className="page">
      <SEO
        title="Shop"
        description="Curated products sourced directly by us, plus trusted partner picks — all in one place."
        path="/"
      />
      <div className="container">
        <div className="hero">
          <span className="hero-eyebrow">New arrivals every week</span>
          <h1>Curated finds, honest prices</h1>
          <p>
            Kuch products hum khud source karke bhejte hain, kuch trusted partners
            (Flipkart) ke through — har product par clearly likha hai kaunsa hai.
          </p>
        </div>

        {loading && (
          <div className="product-grid">
            {[1, 2, 3, 4].map((i) => <div className="skeleton" key={i} />)}
          </div>
        )}

        {!loading && products.length === 0 && (
          <div className="empty-state">
            <h3>Abhi koi product nahi hai</h3>
            <p>Jaldi hi naye products add honge — thodi der baad wapas aana.</p>
          </div>
        )}

        {!loading && products.length > 0 && (
          <div className="product-grid">
            {products.map((p) => (
              <div className="product-card" key={p._id}>
                <span className={`badge ${p.type === "affiliate" ? "badge-affiliate" : "badge-reseller"}`}>
                  {p.type === "affiliate" ? `Via ${p.affiliateSource || "Partner"}` : "Sold by us"}
                </span>
                <div className="img-wrap">
                  {p.image && <img src={p.image} alt={p.name} loading="lazy" />}
                </div>
                <h3 style={{ fontSize: 16 }}>{p.name}</h3>
                <p className="desc">{p.description}</p>
                <p className="price">
                  ₹{p.type === "affiliate" ? p.displayPrice : p.sellingPrice}
                </p>

                {p.type === "affiliate" ? (
                  <button className="btn btn-accent" onClick={() => handleAffiliateClick(p)}>
                    View on {p.affiliateSource || "Partner Site"}
                  </button>
                ) : (
                  <button
                    className="btn"
                    disabled={p.stock <= 0}
                    onClick={() => navigate(`/checkout/${p._id}`)}
                  >
                    {p.stock > 0 ? "Buy Now" : "Out of stock"}
                  </button>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
